-- Original English Java 21 / Spring Boot curriculum.
-- Existing descriptions and lesson content are kept. Matching lesson names are skipped.
-- No automatic rollback: later student/author edits must not be deleted by a rollback.
DO $migration$
DECLARE
    curriculum jsonb := $curriculum$
[
  {
    "name": "Java Development Essentials",
    "description": "Set up a Java 21 development environment, understand types and methods, and build a reproducible Gradle workflow before developing the LMS.",
    "lessons": [
      {
        "name": "JDK, JVM and Your First Program",
        "description": "Compile and run a Java program and distinguish source code, bytecode and the runtime.",
        "content": "<h2>JDK, JVM and Your First Program</h2>\n<p><strong>Learning goal:</strong> Compile and run a Java program and distinguish source code, bytecode and the runtime.</p>\n<h3>Explanation</h3>\n<p>A JDK contains tools such as javac and java. The compiler checks source code and produces class files containing bytecode. The JVM loads these files and executes the program. The Java version selected in an IDE can differ from the one selected by a terminal, so inspect both before debugging a build failure.</p>\n<p>For the examples in this course, use Java 21 without preview features. A public top-level class belongs in a file with the same name. The main method is the entry point of this small console application. System.out is useful while learning; application services will later use structured loggers instead.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">// Save as HelloLms.java\npublic class HelloLms {\n    public static void main(String[] args) {\n        System.out.println(&quot;Welcome to Java Developer&quot;);\n    }\n}\n// Terminal: javac HelloLms.java\n// Terminal: java HelloLms</code></pre>\n<h3>Practice task</h3>\n<p>Create HelloLms.java, compile it from a terminal, and run it. Change the greeting to include your name. Intentionally introduce a misspelled method name and compare a compilation error with a successful run.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>java -version and javac -version use the intended JDK.</li>\n<li>The class prints one greeting without an exception.</li>\n<li>You can explain why running java HelloLms does not include a .class suffix.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Installing a runtime alone is not enough to compile source files. A program compiled for a newer Java release cannot generally run on an older JVM.</p>"
      },
      {
        "name": "Variables, Numeric Types and Conversion",
        "description": "Select suitable types and avoid accidental integer division and overflow.",
        "content": "<h2>Variables, Numeric Types and Conversion</h2>\n<p><strong>Learning goal:</strong> Select suitable types and avoid accidental integer division and overflow.</p>\n<h3>Explanation</h3>\n<p>Variables have declared types, and assignments must be compatible with them. int is suitable for small counts, while long provides a larger range for identifiers. Both have finite ranges. Overflow in ordinary integer arithmetic does not automatically produce an exception; choose explicit checks when accepting untrusted amounts.</p>\n<p>Integer division discards the fractional part. Convert an operand before dividing if a fractional answer is required. double uses binary floating-point and cannot represent every decimal fraction exactly. Use BigDecimal with an explicit rounding policy for decimal monetary calculations, not a double field followed by cosmetic formatting.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">int completed = 3;\nint total = 4;\ndouble progress = (double) completed / total;\nSystem.out.println(progress); // 0.75\nlong lessonId = 5_000_000_000L;\nint safeTotal = Math.addExact(100, 25);\nSystem.out.println(lessonId + &quot;: &quot; + safeTotal);</code></pre>\n<h3>Practice task</h3>\n<p>Implement a completion percentage calculation for completed and total lessons. Decide how zero total is represented and reject negative inputs or completed values greater than total.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>3 of 4 lessons produces 75 percent.</li>\n<li>Zero total has documented behavior without division by zero.</li>\n<li>Invalid ranges are rejected before calculation.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Casting the result of completed / total to double is too late: the integer division has already lost the fraction.</p>"
      },
      {
        "name": "Strings, Null and Immutable Values",
        "description": "Compare text by value and normalize user input deliberately.",
        "content": "<h2>Strings, Null and Immutable Values</h2>\n<p><strong>Learning goal:</strong> Compare text by value and normalize user input deliberately.</p>\n<h3>Explanation</h3>\n<p>String objects are immutable. trim and replace return a new string instead of modifying the original. The == operator compares object references; equals compares string contents. A literal on the left of equals is safe when the other value may be null, while Objects.equals handles two nullable references.</p>\n<p>A missing value and an empty value express different states. Decide whether an optional description can be null and whether a mandatory name is trimmed. Do not silently normalize identifiers or passwords using the same rules as display names. isBlank recognizes whitespace-only strings and is useful for validating human-readable names.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">String rawName = &quot;  Java Developer  &quot;;\nString name = rawName.trim();\nSystem.out.println(name.equals(&quot;Java Developer&quot;)); // true\nSystem.out.println(rawName.length() &gt; name.length()); // true\nString optionalDescription = null;\nSystem.out.println(java.util.Objects.equals(optionalDescription, &quot;&quot;)); // false</code></pre>\n<h3>Practice task</h3>\n<p>Write normalizeCourseName(String value) that rejects null and blank input, trims surrounding whitespace and retains internal spaces. Add examples for a normal name, a blank string and a null reference.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>&quot;  Java Core  &quot; becomes &quot;Java Core&quot;.</li>\n<li>Null and whitespace-only values are rejected.</li>\n<li>Two different String instances with equal text compare as equal.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Calling trim without assigning its return value leaves the original reference unchanged. Calling a method on null causes NullPointerException.</p>"
      },
      {
        "name": "Methods, Packages and the Gradle Wrapper",
        "description": "Organize reusable logic and run the same build outside the IDE.",
        "content": "<h2>Methods, Packages and the Gradle Wrapper</h2>\n<p><strong>Learning goal:</strong> Organize reusable logic and run the same build outside the IDE.</p>\n<h3>Explanation</h3>\n<p>A method defines a contract through its parameters, return type and behavior. Keep a calculation independent from console input so that it can be tested without a running application. Package names organize classes and affect visibility; public types are accessible from other packages, while package-private types are not.</p>\n<p>The Gradle wrapper records the Gradle distribution used by a project. Commit its scripts, properties and wrapper JAR so another developer does not need a matching global Gradle installation. Java toolchains select a compiler version, but the required JDK must be available or provisioned. Distinguish compileJava, test and bootJar: compiling source alone does not run tests.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">package kz.edu.lms.util;\n\npublic final class Progress {\n    private Progress() { }\n    public static int remaining(int completed, int total) {\n        if (completed &lt; 0 || total &lt; completed) {\n            throw new IllegalArgumentException(&quot;Invalid progress&quot;);\n        }\n        return total - completed;\n    }\n}\n// Windows terminal: .\\gradlew.bat test</code></pre>\n<h3>Practice task</h3>\n<p>Extract a reusable progress calculation into a package, call it from a second class, and execute compileJava with the project wrapper. Explain which command creates the executable Spring Boot JAR.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The helper can be called from another package.</li>\n<li>The wrapper compiles with the configured Java version.</li>\n<li>The calculation contains no console interaction or repository access.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>A successful IDE run does not guarantee the wrapper build works. Verify the command-line build before publishing an image.</p>"
      }
    ]
  },
  {
    "name": "Control Flow",
    "description": "Use conditions, loops and small functions to implement predictable validation and collection processing.",
    "lessons": [
      {
        "name": "Switch Expressions and Exhaustive Choices",
        "description": "Use a switch expression to map a finite domain to a value.",
        "content": "<h2>Switch Expressions and Exhaustive Choices</h2>\n<p><strong>Learning goal:</strong> Use a switch expression to map a finite domain to a value.</p>\n<h3>Explanation</h3>\n<p>A switch expression returns a value, which reduces the need for a mutable variable assigned in several branches. Arrow cases do not fall through into the next branch. When every enum constant is handled, the compiler can verify exhaustiveness without a generic default branch.</p>\n<p>Use an enum for a fixed vocabulary such as DRAFT, PUBLISHED and ARCHIVED rather than repeating string literals across the program. A display label is separate from the stored enum name. Think about missing values before switching: ordinary enum switches in these examples assume a non-null argument. Validation at the boundary makes that expectation explicit.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">enum CourseState { DRAFT, PUBLISHED, ARCHIVED }\n\nstatic String label(CourseState state) {\n    return switch (state) {\n        case DRAFT -&gt; &quot;Work in progress&quot;;\n        case PUBLISHED -&gt; &quot;Available to students&quot;;\n        case ARCHIVED -&gt; &quot;Read-only archive&quot;;\n    };\n}</code></pre>\n<h3>Practice task</h3>\n<p>Implement a label and an isEditable function for all three states. Then add a new enum constant and observe which switch expressions need to be updated.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Every state has a label.</li>\n<li>Archived courses are not editable.</li>\n<li>Adding a state exposes any incomplete exhaustive switch during compilation.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Accepting arbitrary strings for state moves typo detection from compilation to runtime. Avoid using a catch-all default when a new state should require a deliberate decision.</p>"
      },
      {
        "name": "Loop Invariants and Boundary Cases",
        "description": "Reason about what remains true while a loop processes data.",
        "content": "<h2>Loop Invariants and Boundary Cases</h2>\n<p><strong>Learning goal:</strong> Reason about what remains true while a loop processes data.</p>\n<h3>Explanation</h3>\n<p>An invariant is a property that stays true throughout a loop. For a running sum, the accumulator should equal the sum of elements already visited. Naming this property helps locate off-by-one mistakes: the initialization, condition and update must agree about which elements have been processed.</p>\n<p>Array indexes start at zero and stop before length. A loop with index &lt;= length accesses one element too far. An empty array should usually require no special loop branch: initialization and a correct condition already handle it. Decide whether empty input has a useful result, such as a zero sum, or should be rejected by the method contract.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">int[] durations = {10, 15, 20};\nint total = 0;\nfor (int index = 0; index &lt; durations.length; index++) {\n    total += durations[index];\n}\nSystem.out.println(total); // 45</code></pre>\n<h3>Practice task</h3>\n<p>Compute the total and maximum lesson duration from an int array. Specify the maximum result for empty input rather than choosing an accidental sentinel.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Total duration is 45 for the example.</li>\n<li>One-element input is processed exactly once.</li>\n<li>Empty input does not cause an out-of-bounds access.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Setting a maximum to zero only works if negative values are forbidden. State and validate that restriction instead of relying on sample data.</p>"
      },
      {
        "name": "Guard Clauses and Validation Order",
        "description": "Reject invalid inputs early and keep the successful path readable.",
        "content": "<h2>Guard Clauses and Validation Order</h2>\n<p><strong>Learning goal:</strong> Reject invalid inputs early and keep the successful path readable.</p>\n<h3>Explanation</h3>\n<p>Guard clauses return or throw near the beginning of a method when a precondition is not met. This avoids several nested if blocks around the successful operation. Validate values before using them: check a reference for null before calling its methods, and validate a divisor before dividing.</p>\n<p>A method should not perform partial changes and only then discover an invalid request. Gather and validate inputs first, then perform the state change. At an API boundary, annotation-based validation handles basic shape constraints; the service still checks business rules such as whether the chosen parent exists.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">static int nextPosition(Integer position) {\n    if (position == null) {\n        throw new IllegalArgumentException(&quot;Position is required&quot;);\n    }\n    if (position &lt; 1) {\n        throw new IllegalArgumentException(&quot;Position must be positive&quot;);\n    }\n    return Math.addExact(position, 1);\n}</code></pre>\n<h3>Practice task</h3>\n<p>Write a publish validator that requires a nonblank course name and at least one lesson. Keep validation separate from changing the course state.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Each invalid case has a meaningful message.</li>\n<li>Invalid input does not mutate the course.</li>\n<li>The successful path is readable without deeply nested conditions.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Catching every exception and returning false can hide programming defects. Catch only failures that the method is designed to handle.</p>"
      },
      {
        "name": "Workshop: Build a Console Gradebook",
        "description": "Combine methods, loops and validation into a small complete program.",
        "content": "<h2>Workshop: Build a Console Gradebook</h2>\n<p><strong>Learning goal:</strong> Combine methods, loops and validation into a small complete program.</p>\n<h3>Explanation</h3>\n<p>A gradebook transforms raw scores into a summary. Separate the concerns: one function validates a score, another computes a mean, and another assigns a grade. This makes each rule independently testable and avoids mixing user-interface prompts with calculation logic.</p>\n<p>Document the grading thresholds before writing conditions. Equality at a boundary matters: a score of 60 should not fall between two ranges. Preserve fractional precision when calculating the mean, and explicitly decide whether the overall grade uses the unrounded or rounded mean. Reject empty input if the mean has no meaning in your contract.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">static double mean(int[] scores) {\n    if (scores.length == 0) throw new IllegalArgumentException(&quot;No scores&quot;);\n    long total = 0;\n    for (int score : scores) {\n        if (score &lt; 0 || score &gt; 100) throw new IllegalArgumentException(&quot;Invalid score&quot;);\n        total += score;\n    }\n    return (double) total / scores.length;\n}</code></pre>\n<h3>Practice task</h3>\n<p>Build a console report with student count, average score, highest score and number of passing students. Use a passing threshold of 60 and keep sample data separate from the calculation methods.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>[50, 60, 100] has two passing scores and an average of 70.</li>\n<li>An empty group has the documented error.</li>\n<li>Scores -1 and 101 are rejected.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Averages should not be computed using repeated integer division inside the loop. Sum first and divide once with the intended numeric type.</p>"
      }
    ]
  },
  {
    "name": "Object-Oriented Programming",
    "description": "Model domain behavior, use interfaces and composition, and understand identity and value objects.",
    "lessons": [
      {
        "name": "Interfaces and Dependency Boundaries",
        "description": "Depend on a behavior contract so implementations can change independently.",
        "content": "<h2>Interfaces and Dependency Boundaries</h2>\n<p><strong>Learning goal:</strong> Depend on a behavior contract so implementations can change independently.</p>\n<h3>Explanation</h3>\n<p>An interface describes operations that a caller needs without choosing how they are implemented. A notification service can depend on a Sender interface while one implementation writes to a console and another uses an external provider. The caller should not construct a concrete dependency inside every method.</p>\n<p>Constructor injection makes required collaborators visible and permits a test to supply a fake. An interface is useful when it defines a meaningful boundary; creating one for every class by habit adds files without necessarily improving the design. Keep domain decisions in the service and transport details in an adapter.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">interface Sender { void send(String message); }\nclass NotificationService {\n    private final Sender sender;\n    NotificationService(Sender sender) { this.sender = sender; }\n    void announce(String courseName) {\n        sender.send(&quot;New course: &quot; + courseName);\n    }\n}\n// Example wiring: new NotificationService(System.out::println)</code></pre>\n<h3>Practice task</h3>\n<p>Create a recording Sender that stores messages in a List. Use it to check that announcing a course sends exactly one message containing the course name.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The service depends on Sender, not a console implementation.</li>\n<li>A recording implementation works without network access.</li>\n<li>The service can be created through its constructor in a plain Java test.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>An interface alone does not remove coupling if the service immediately casts it to a concrete implementation.</p>"
      },
      {
        "name": "Composition, Inheritance and Responsibilities",
        "description": "Choose object relationships that match the domain instead of reusing code through inheritance.",
        "content": "<h2>Composition, Inheritance and Responsibilities</h2>\n<p><strong>Learning goal:</strong> Choose object relationships that match the domain instead of reusing code through inheritance.</p>\n<h3>Explanation</h3>\n<p>Inheritance models an is-a relationship and creates a contract between the parent type and all subtypes. A subtype should be usable where its parent is expected without surprising the caller. A Course is not a Chapter, and a Chapter is not a Lesson: these are containment relationships better expressed through fields or database associations.</p>\n<p>Composition lets one object delegate a task to another. It often makes behavior easier to vary than a deep inheritance hierarchy. The LMS BaseEntity is a small shared persistence structure; it should not become a dumping ground for unrelated business rules. Keep course publishing or lesson ordering in the relevant service or domain object.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">class CourseSummary {\n    private final java.util.List&lt;String&gt; lessonNames;\n    CourseSummary(java.util.List&lt;String&gt; lessonNames) {\n        this.lessonNames = java.util.List.copyOf(lessonNames);\n    }\n    int lessonCount() { return lessonNames.size(); }\n}</code></pre>\n<h3>Practice task</h3>\n<p>Model a course summary that contains lesson names and a separate formatter that turns the summary into text. Explain why neither type needs to inherit from the other.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The summary stores an independent immutable list snapshot.</li>\n<li>Formatting can change without changing lesson counting.</li>\n<li>No subtype promises an operation it cannot support.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Extending a class only to reuse a few lines exposes its entire inheritance contract. Delegation is often the smaller dependency.</p>"
      },
      {
        "name": "Records, Equality and Hash Codes",
        "description": "Distinguish value-based DTOs from mutable entities with generated identity.",
        "content": "<h2>Records, Equality and Hash Codes</h2>\n<p><strong>Learning goal:</strong> Distinguish value-based DTOs from mutable entities with generated identity.</p>\n<h3>Explanation</h3>\n<p>A record provides a compact value carrier with component accessors, equals, hashCode and toString. It is useful for request and response DTOs. Record components are final references, but a component may still point to a mutable collection; make a defensive copy when the contract requires an immutable snapshot.</p>\n<p>Hash-based collections rely on equality and hashCode remaining consistent. Changing a field used by hashCode after adding an object to a HashSet can make lookups fail. Database entities introduce additional concerns because an ID may be assigned only after persistence. Avoid automatically generating entity equality from every field and relationship.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">record CourseLabel(long id, String name) { }\nvar first = new CourseLabel(1L, &quot;Java Developer&quot;);\nvar second = new CourseLabel(1L, &quot;Java Developer&quot;);\nvar labels = new java.util.HashSet&lt;CourseLabel&gt;();\nlabels.add(first);\nlabels.add(second);\nSystem.out.println(labels.size()); // 1</code></pre>\n<h3>Practice task</h3>\n<p>Create a record for a lesson summary and demonstrate equality with two equivalent instances. Then add a List component and ensure the constructor makes a defensive copy.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Equivalent values compare equal and share a hash code.</li>\n<li>External mutation cannot change the copied list.</li>\n<li>You can explain why JPA entities and DTO records have different lifecycles.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Lombok @Data on entities may include lazy relationships in generated equality and string methods. Use explicit decisions instead of applying it indiscriminately.</p>"
      },
      {
        "name": "Workshop: Model Course Enrollment Rules",
        "description": "Express a business invariant through a small object API.",
        "content": "<h2>Workshop: Model Course Enrollment Rules</h2>\n<p><strong>Learning goal:</strong> Express a business invariant through a small object API.</p>\n<h3>Explanation</h3>\n<p>An enrollment model connects a student to a course. Start by defining allowed states and transitions: for example ACTIVE can become COMPLETED, while COMPLETED cannot silently become ACTIVE without an explicit reset operation. A boolean field alone may become unclear when cancellation or expiration is later introduced.</p>\n<p>Methods should name an intention rather than expose every field setter. complete() can enforce a rule in one place, while setStatus() allows callers to skip that rule. Keep persistence identifiers separate from business decisions. This workshop uses an in-memory model; authorization and concurrent updates belong to later application layers.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">enum EnrollmentState { ACTIVE, COMPLETED }\nclass Enrollment {\n    private EnrollmentState state = EnrollmentState.ACTIVE;\n    void complete() {\n        if (state != EnrollmentState.ACTIVE) {\n            throw new IllegalStateException(&quot;Enrollment already completed&quot;);\n        }\n        state = EnrollmentState.COMPLETED;\n    }\n    EnrollmentState state() { return state; }\n}</code></pre>\n<h3>Practice task</h3>\n<p>Implement an Enrollment with studentId, courseId and complete(). Validate identifiers in construction and write examples of a successful and repeated completion.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>New enrollment starts ACTIVE.</li>\n<li>A valid completion moves to COMPLETED.</li>\n<li>Repeated completion follows a documented policy and cannot corrupt state.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Do not add authentication or a database merely to prove a state transition. Establish the domain behavior first.</p>"
      }
    ]
  },
  {
    "name": "Collections and Generics",
    "description": "Choose lists, sets and maps, use generic contracts, and transform course data without losing ordering or type safety.",
    "lessons": [
      {
        "name": "Lists, Sets and Choosing a Collection",
        "description": "Select a collection according to ordering, duplicates and lookup requirements.",
        "content": "<h2>Lists, Sets and Choosing a Collection</h2>\n<p><strong>Learning goal:</strong> Select a collection according to ordering, duplicates and lookup requirements.</p>\n<h3>Explanation</h3>\n<p>A List preserves element order and permits duplicates. A Set represents membership without duplicate values according to equality. These are different contracts: the implementation should follow the requirement, not just a familiar class name. ArrayList suits indexed access and append-heavy workloads; HashSet is useful for membership checks without a sorted-order guarantee.</p>\n<p>A course syllabus normally needs ordered lessons, while a collection of unique enrollment IDs may be a set. Converting a list to a set can discard duplicates and change iteration order. If encounter order matters while removing duplicates, LinkedHashSet is a suitable option. Unmodifiable collections prevent structural updates through that reference but do not make contained mutable objects immutable.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">var names = java.util.List.of(&quot;Java&quot;, &quot;SQL&quot;, &quot;Java&quot;);\nvar unique = new java.util.LinkedHashSet&lt;&gt;(names);\nSystem.out.println(unique); // [Java, SQL]\nvar orderedCopy = new java.util.ArrayList&lt;&gt;(unique);\norderedCopy.add(&quot;Spring&quot;);</code></pre>\n<h3>Practice task</h3>\n<p>Given repeated course tags, produce an ordered list of unique tags while preserving the first occurrence. Leave the input list unchanged.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Java, SQL, Java becomes Java, SQL.</li>\n<li>The input is not modified.</li>\n<li>Adding to a List.of result is recognized as unsupported.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>HashSet does not promise the same iteration order as the input. Never use its incidental order to define chapter positions.</p>"
      },
      {
        "name": "Maps and Grouping by Identifier",
        "description": "Use key-value lookup and define a policy for duplicate keys.",
        "content": "<h2>Maps and Grouping by Identifier</h2>\n<p><strong>Learning goal:</strong> Use key-value lookup and define a policy for duplicate keys.</p>\n<h3>Explanation</h3>\n<p>A Map associates one value with each key. It is useful for looking up a course by ID instead of scanning a list repeatedly. A later put for the same key replaces its previous value, so accidental duplicate keys can hide data. Decide whether replacement, rejection or grouping matches the task.</p>\n<p>computeIfAbsent can initialize a collection when a key first appears. This works well for grouping lesson names by chapter ID. Map keys need stable equality and hash codes, and mutable entities are usually poor choices for keys. Use a stable scalar ID or an immutable value type instead. Missing keys and keys mapped to null can be distinguished with containsKey.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">java.util.Map&lt;Long, java.util.List&lt;String&gt;&gt; lessons = new java.util.HashMap&lt;&gt;();\nlessons.computeIfAbsent(10L, id -&gt; new java.util.ArrayList&lt;&gt;()).add(&quot;Variables&quot;);\nlessons.computeIfAbsent(10L, id -&gt; new java.util.ArrayList&lt;&gt;()).add(&quot;Methods&quot;);\nSystem.out.println(lessons.get(10L).size()); // 2</code></pre>\n<h3>Practice task</h3>\n<p>Group lesson titles by chapter ID from a sequence of input pairs. Return an empty collection for a chapter with no lessons without inserting that chapter into the map.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Two lessons with the same chapter ID belong to one group.</li>\n<li>Different chapter IDs stay separate.</li>\n<li>Reading a missing group does not mutate the map.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Using getOrDefault with a new list and then adding to that list does not automatically store the default list in the map.</p>"
      },
      {
        "name": "Generics and Type-Safe Reuse",
        "description": "Write a reusable method without raw collections or unchecked casts.",
        "content": "<h2>Generics and Type-Safe Reuse</h2>\n<p><strong>Learning goal:</strong> Write a reusable method without raw collections or unchecked casts.</p>\n<h3>Explanation</h3>\n<p>Generics move many type errors to compilation. A List&lt;String&gt; can be consumed without casting each element, while a raw List discards that protection. Generic methods introduce type parameters before the return type and can preserve the relationship between input and output types.</p>\n<p>Generics are invariant: a List&lt;Integer&gt; is not a List&lt;Number&gt;. A producer of numbers can be accepted as List&lt;? extends Number&gt;, which allows reading Number values but restricts adding arbitrary numbers. Use a lower bound when the caller needs to provide a destination that can consume a type. Prefer the simplest signature that communicates the contract.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">static &lt;T&gt; java.util.Optional&lt;T&gt; first(java.util.List&lt;T&gt; values) {\n    return values.isEmpty() ? java.util.Optional.empty()\n                            : java.util.Optional.ofNullable(values.get(0));\n}\n// first(List.of(&quot;Java&quot;, &quot;SQL&quot;)) returns Optional&lt;String&gt;</code></pre>\n<h3>Practice task</h3>\n<p>Write first for strings and numeric IDs. Then write a method that sums a List&lt;? extends Number&gt; using doubleValue and describe its precision limitations.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>No unchecked cast or raw type warning is needed.</li>\n<li>Empty input produces Optional.empty.</li>\n<li>List&lt;Integer&gt; and List&lt;Double&gt; are accepted by the sum method.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>A wildcard is not a runtime conversion. It describes permitted operations at compile time; it does not change the stored objects.</p>"
      },
      {
        "name": "Streams, Sorting and Collecting Results",
        "description": "Build a readable data pipeline and make ordering explicit.",
        "content": "<h2>Streams, Sorting and Collecting Results</h2>\n<p><strong>Learning goal:</strong> Build a readable data pipeline and make ordering explicit.</p>\n<h3>Explanation</h3>\n<p>A stream describes a pipeline over elements. Intermediate operations such as filter and map are lazy, while a terminal operation triggers traversal. Streams are single-use; create another stream when a second result is needed. Avoid hidden mutation of external lists from inside a pipeline.</p>\n<p>A comparator can define more than one ordering field. Sorting chapters by position and then ID gives a deterministic tie-breaker when positions match. A stream over data already loaded in memory does not reduce the amount read from the database. Use repository pagination and filtering when the dataset should be restricted before it enters the application.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">record Item(long id, int position, String name) { }\nvar items = java.util.List.of(new Item(2, 1, &quot;SQL&quot;), new Item(1, 1, &quot;Java&quot;));\nvar names = items.stream()\n    .sorted(java.util.Comparator.comparingInt(Item::position).thenComparingLong(Item::id))\n    .map(Item::name)\n    .toList();\nSystem.out.println(names); // [Java, SQL]</code></pre>\n<h3>Practice task</h3>\n<p>Transform a list of chapter summaries into sorted nonblank names. Define the tie-breaker and verify the result on duplicate positions.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Position is the primary sort key and ID resolves ties.</li>\n<li>Blank names are excluded according to the chosen rule.</li>\n<li>The source collection remains unchanged.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Calling parallelStream is not an automatic speed improvement. Shared mutable state can introduce races and small workloads can become slower.</p>"
      }
    ]
  },
  {
    "name": "Exceptions, Files and Time",
    "description": "Design error contracts, release resources reliably and handle text files and timestamps explicitly.",
    "lessons": [
      {
        "name": "Exception Types and Preserving Causes",
        "description": "Choose meaningful exceptions and retain diagnostic context when translating them.",
        "content": "<h2>Exception Types and Preserving Causes</h2>\n<p><strong>Learning goal:</strong> Choose meaningful exceptions and retain diagnostic context when translating them.</p>\n<h3>Explanation</h3>\n<p>An exception interrupts the normal path and carries information about a failure. Checked exceptions must be caught or declared; unchecked exceptions extend RuntimeException and do not have that compiler requirement. Neither category by itself means an error is harmless or fatal.</p>\n<p>Translate exceptions at a layer that can add meaning. A storage error can become an application-specific conflict while retaining the original cause for logs. Do not expose SQL text or internal stack traces to clients. In this LMS assignment, IllegalArgumentException represents a missing entity and the advice maps it to 404; that is a project convention, not a universal meaning of the Java exception type.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">static int parsePositive(String value) {\n    try {\n        int result = Integer.parseInt(value);\n        if (result &lt; 1) throw new IllegalArgumentException(&quot;Value must be positive&quot;);\n        return result;\n    } catch (NumberFormatException cause) {\n        throw new IllegalArgumentException(&quot;Value must be an integer&quot;, cause);\n    }\n}</code></pre>\n<h3>Practice task</h3>\n<p>Exercise the parser with 7, 0, abc and a number beyond the int range. Inspect both the public message and the nested cause.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>7 succeeds.</li>\n<li>Zero is rejected as nonpositive.</li>\n<li>Malformed and out-of-range numeric text keep the original parsing cause.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>An empty catch block turns a known failure into silent corruption or a later unrelated failure. Either recover deliberately or propagate meaningful information.</p>"
      },
      {
        "name": "Try-with-Resources and Reliable Cleanup",
        "description": "Close resources even when processing fails.",
        "content": "<h2>Try-with-Resources and Reliable Cleanup</h2>\n<p><strong>Learning goal:</strong> Close resources even when processing fails.</p>\n<h3>Explanation</h3>\n<p>Files, database connections and sockets often hold operating-system resources that must be released. Garbage collection manages Java memory but is not a timely cleanup strategy for these resources. try-with-resources invokes close on resources that implement AutoCloseable, including when the body throws.</p>\n<p>Declare the resource inside the try header to make its lifetime obvious. Resources close in reverse declaration order. If the body and close both fail, Java retains the body exception and attaches the cleanup failure as a suppressed exception. Keep resource handling separate from domain validation so each responsibility remains clear.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">java.nio.file.Path path = java.nio.file.Path.of(&quot;course.txt&quot;);\ntry (var reader = java.nio.file.Files.newBufferedReader(path, java.nio.charset.StandardCharsets.UTF_8)) {\n    String firstLine = reader.readLine();\n    System.out.println(firstLine);\n}\n// The surrounding method declares throws IOException or handles it.</code></pre>\n<h3>Practice task</h3>\n<p>Read a file using a method that declares IOException. Introduce an exception during processing and demonstrate that the resource still closes using a small recording AutoCloseable implementation.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Cleanup occurs after normal completion.</li>\n<li>Cleanup also occurs when processing throws.</li>\n<li>The caller can distinguish an empty file from a missing file.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Do not return a Stream backed by a closed file resource. Consume it within its lifetime or document who owns closing it.</p>"
      },
      {
        "name": "UTF-8 Files and Safe Path Handling",
        "description": "Read and write predictable text and restrict paths to an intended directory.",
        "content": "<h2>UTF-8 Files and Safe Path Handling</h2>\n<p><strong>Learning goal:</strong> Read and write predictable text and restrict paths to an intended directory.</p>\n<h3>Explanation</h3>\n<p>Text is encoded as bytes, and the reader must use the same encoding as the writer. UTF-8 makes an explicit and widely supported choice for lesson text containing punctuation or non-English characters. Files.readString is convenient for bounded files, but loading a very large upload entirely into memory is not appropriate.</p>\n<p>A user-supplied filename should not grant access outside the application&#x27;s storage root. Resolve and normalize the path and verify it stays under that root. Lexical checks alone do not protect against symbolic-link changes; a production upload design must also control directory ownership, links and file sizes. This example introduces the boundary, not a complete upload service.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">var root = java.nio.file.Path.of(&quot;uploads&quot;).toAbsolutePath().normalize();\nvar target = root.resolve(&quot;lesson.txt&quot;).normalize();\nif (!target.startsWith(root)) throw new IllegalArgumentException(&quot;Invalid path&quot;);\njava.nio.file.Files.createDirectories(root);\njava.nio.file.Files.writeString(target, &quot;Java lesson&quot;, java.nio.charset.StandardCharsets.UTF_8);</code></pre>\n<h3>Practice task</h3>\n<p>Write and read a UTF-8 lesson note in a temporary directory. Add a test for ../outside.txt and ensure it is rejected before writing.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The text round-trips without changed characters.</li>\n<li>A parent-directory escape is rejected.</li>\n<li>Test files are isolated from project source files.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Concatenating a directory and untrusted filename as strings does not validate a path. File-extension checks are also not a substitute for content and size validation.</p>"
      },
      {
        "name": "LocalDateTime, Instant and Time Zones",
        "description": "Represent dates and instants according to their meaning.",
        "content": "<h2>LocalDateTime, Instant and Time Zones</h2>\n<p><strong>Learning goal:</strong> Represent dates and instants according to their meaning.</p>\n<h3>Explanation</h3>\n<p>LocalDate represents a calendar date, LocalDateTime a date and clock time without an offset, and Instant a point on the UTC timeline. Choose based on meaning: a birthday is a date, while a recorded event across time zones is naturally an instant. A zone converts between timeline and local presentation.</p>\n<p>The current LMS uses LocalDateTime audit columns, so it must apply a consistent timezone convention across application instances. A formatted timestamp without an offset cannot identify a universal instant by itself. For deterministic tests, inject a Clock rather than directly calling the system clock everywhere. Avoid timing assertions that depend on an exact wall-clock second.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">java.time.Clock clock = java.time.Clock.fixed(\n    java.time.Instant.parse(&quot;2026-01-01T10:00:00Z&quot;), java.time.ZoneOffset.UTC);\nvar now = java.time.Instant.now(clock);\nvar local = now.atZone(java.time.ZoneId.of(&quot;Asia/Almaty&quot;));\nSystem.out.println(local.toInstant().equals(now)); // true</code></pre>\n<h3>Practice task</h3>\n<p>Build a method that calculates a seven-day deadline from an injected Clock. Return an Instant and format it in two zones only at presentation time.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>A fixed Clock gives a reproducible deadline.</li>\n<li>Both displayed zones represent the same instant.</li>\n<li>The persistence timezone convention is documented.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Adding a literal timezone suffix to a LocalDateTime string does not convert the value. Conversion requires knowing what zone the local value belongs to.</p>"
      }
    ]
  },
  {
    "name": "Modern Java and Concurrency",
    "description": "Use lambdas and Optional deliberately, understand shared state and apply virtual threads to appropriate workloads.",
    "lessons": [
      {
        "name": "Lambdas and Functional Interfaces",
        "description": "Pass behavior as a value without hiding complex business logic.",
        "content": "<h2>Lambdas and Functional Interfaces</h2>\n<p><strong>Learning goal:</strong> Pass behavior as a value without hiding complex business logic.</p>\n<h3>Explanation</h3>\n<p>A functional interface has one abstract method and can be implemented by a lambda. Predicate&lt;T&gt; answers a boolean question, Function&lt;T,R&gt; transforms a value, and Consumer&lt;T&gt; performs an action without returning a result. Method references are a concise option when an existing method already matches the needed signature.</p>\n<p>Captured local variables must be final or effectively final. This restriction does not make an object referenced by a variable immutable. Keep lambdas short and extract named methods when a condition needs explanation or reuse. Readability matters more than making every method a one-line stream pipeline.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">java.util.function.Predicate&lt;String&gt; usable = value -&gt; value != null &amp;&amp; !value.isBlank();\njava.util.function.Function&lt;String, String&gt; normalize = String::trim;\nvar names = java.util.List.of(&quot; Java &quot;, &quot;&quot;, &quot;SQL&quot;).stream()\n    .filter(usable)\n    .map(normalize)\n    .toList();</code></pre>\n<h3>Practice task</h3>\n<p>Compose a predicate that accepts names between 1 and 255 characters after trimming. Extract it into a named method if the expression becomes difficult to read.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Blank values are rejected.</li>\n<li>A valid value with surrounding spaces is accepted after normalization.</li>\n<li>The input collection is not mutated.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>A Consumer that changes shared state is not automatically safe just because it is expressed as a lambda.</p>"
      },
      {
        "name": "Optional and Missing Data Contracts",
        "description": "Use Optional for a possibly absent result and handle absence at the correct layer.",
        "content": "<h2>Optional and Missing Data Contracts</h2>\n<p><strong>Learning goal:</strong> Use Optional for a possibly absent result and handle absence at the correct layer.</p>\n<h3>Explanation</h3>\n<p>Optional communicates that a result may be absent. Repository findById returns Optional because the requested row may not exist. orElseThrow lets the service choose the missing-record behavior, while map transforms a present value without a separate null check.</p>\n<p>A list or page normally represents absence with an empty collection rather than Optional&lt;List&lt;T&gt;&gt;. The distinction between an empty child list and a missing parent is a domain decision: this LMS returns an empty page for an existing chapter with no lessons and 404 for a nonexistent chapter. Do not call get on an Optional unless presence has already been established.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">java.util.Optional&lt;String&gt; value = java.util.Optional.of(&quot; Java &quot;);\nString name = value.map(String::trim)\n    .filter(text -&gt; !text.isEmpty())\n    .orElseThrow(() -&gt; new IllegalArgumentException(&quot;Name missing&quot;));\nSystem.out.println(name);</code></pre>\n<h3>Practice task</h3>\n<p>Implement an in-memory lookup by course ID returning Optional. At the calling layer, turn absence into a meaningful exception and transform presence into a DTO.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>An existing ID returns its value.</li>\n<li>A missing ID follows the documented error path.</li>\n<li>No nullable Optional reference is returned.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>orElse evaluates its fallback expression eagerly. Use orElseGet when creating the fallback is expensive or has side effects.</p>"
      },
      {
        "name": "Race Conditions and Atomic Operations",
        "description": "Recognize that a compound operation can fail under concurrent execution.",
        "content": "<h2>Race Conditions and Atomic Operations</h2>\n<p><strong>Learning goal:</strong> Recognize that a compound operation can fail under concurrent execution.</p>\n<h3>Explanation</h3>\n<p>A race occurs when correctness depends on the timing of concurrent operations. Incrementing a shared integer consists of reading, adding and writing; two threads can read the same old value and lose an increment. AtomicInteger provides atomic operations for one integer, but it does not make a multi-object business workflow atomic.</p>\n<p>Database operations have similar gaps. Checking whether a chapter has lessons and then deleting it allows another transaction to insert a lesson between those steps. Database constraints remain necessary even when services perform friendly prechecks. Use a transaction, constraint or explicit lock according to the rule rather than assuming Java synchronization protects all application instances.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">var counter = new java.util.concurrent.atomic.AtomicInteger();\njava.util.stream.IntStream.range(0, 1000).parallel()\n    .forEach(index -&gt; counter.incrementAndGet());\nSystem.out.println(counter.get()); // 1000</code></pre>\n<h3>Practice task</h3>\n<p>Compare an atomic counter with an unsafe mutable counter under repeated concurrent increments. Explain why a race might not appear on every run and why that does not prove correctness.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The atomic implementation always reaches the expected count.</li>\n<li>The explanation identifies the read-modify-write sequence.</li>\n<li>You distinguish a JVM lock from a database constraint.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Using a thread-safe collection does not automatically make a separate check-then-act sequence atomic.</p>"
      },
      {
        "name": "Virtual Threads and Blocking Work",
        "description": "Use Java 21 virtual threads while keeping resource limits explicit.",
        "content": "<h2>Virtual Threads and Blocking Work</h2>\n<p><strong>Learning goal:</strong> Use Java 21 virtual threads while keeping resource limits explicit.</p>\n<h3>Explanation</h3>\n<p>Virtual threads are lightweight threads managed by the JVM. They are useful for many tasks that spend time waiting on blocking I/O. They do not make a CPU-intensive calculation execute faster than the available processors, and they do not create extra database connections.</p>\n<p>An executor can create a virtual thread per task. Always define how results, failures and cancellation are handled. Resource pools still bound throughput: a database pool with ten connections serves only a limited number of concurrent database operations. Do not add concurrency to a service until you can explain the bottleneck and keep transaction context within the intended execution boundary.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">try (var executor = java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()) {\n    var first = executor.submit(() -&gt; &quot;Course summary&quot;);\n    var second = executor.submit(() -&gt; &quot;Lesson summary&quot;);\n    System.out.println(first.get() + &quot; | &quot; + second.get());\n}\n// The surrounding method handles InterruptedException and ExecutionException.</code></pre>\n<h3>Practice task</h3>\n<p>Run several independent simulated lookups with a virtual-thread executor. Add one task that fails and handle the resulting ExecutionException without losing its cause.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The executor is closed.</li>\n<li>Task failures are observed by the caller.</li>\n<li>You can explain why the database pool still limits concurrent queries.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Do not assume a transaction started on one thread automatically follows work submitted to another thread.</p>"
      }
    ]
  },
  {
    "name": "SQL and PostgreSQL",
    "description": "Design related tables, query course data, enforce constraints and manage changes with Liquibase.",
    "lessons": [
      {
        "name": "Tables, Keys and Relationships",
        "description": "Translate the LMS model into a relational schema.",
        "content": "<h2>Tables, Keys and Relationships</h2>\n<p><strong>Learning goal:</strong> Translate the LMS model into a relational schema.</p>\n<h3>Explanation</h3>\n<p>A primary key uniquely identifies a row, and a foreign key constrains a reference to another table. In this LMS, chapter.course_id references courses.id and lesson.chapter_id references chapter.id. Constraints protect relationships even when writes bypass Java services.</p>\n<p>NOT NULL forbids missing values but does not reject empty strings. Domain validation and database constraints solve different problems. Generated identity values let PostgreSQL assign IDs. Hard-coded seed IDs can collide with existing records or leave the identity sequence behind; INSERT RETURNING provides a generated parent ID for related inserts.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">CREATE TABLE workshop_course (\n  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  name VARCHAR(255) NOT NULL\n);\nINSERT INTO workshop_course(name) VALUES (&#x27;Java Developer&#x27;) RETURNING id;\n-- Use a disposable training schema.</code></pre>\n<h3>Practice task</h3>\n<p>Create workshop_course and workshop_chapter in a training database. Add a mandatory foreign key and attempt a child insert with a nonexistent parent.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>A valid parent-child insert succeeds.</li>\n<li>A nonexistent parent is rejected.</li>\n<li>You can explain the deletion behavior chosen for the foreign key.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>A column named course_id does not become a foreign key until the constraint is declared.&#x27;, &#x27;sql</p>"
      },
      {
        "name": "SELECT, JOIN and Stable Ordering",
        "description": "Retrieve related rows without relying on physical storage order.",
        "content": "<h2>SELECT, JOIN and Stable Ordering</h2>\n<p><strong>Learning goal:</strong> Retrieve related rows without relying on physical storage order.</p>\n<h3>Explanation</h3>\n<p>JOIN combines related records through a condition. An inner join returns matching rows, while a left join retains unmatched rows from the left table. Select the needed columns instead of treating SELECT * as a public API contract.</p>\n<p>SQL promises no row order without ORDER BY. Sorting lessons by sort_order and id creates a deterministic tie-breaker. A filter on a right-side column in WHERE after a left join can remove unmatched rows. Move that condition into ON when it should restrict matches while retaining the left row. For counts after a left join, count the child ID rather than counting every result row.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">SELECT c.name AS course_name, ch.name AS chapter_name, l.name AS lesson_name\nFROM courses c\nJOIN chapter ch ON ch.course_id = c.id\nLEFT JOIN lesson l ON l.chapter_id = ch.id\nWHERE c.name = &#x27;Java Developer&#x27;\nORDER BY ch.sort_order, ch.id, l.sort_order, l.id;</code></pre>\n<h3>Practice task</h3>\n<p>Query all chapters and their lesson counts, including chapters with no lessons. Fetch a second page of lessons using a stable order.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>An empty chapter appears with count zero.</li>\n<li>Ordering resolves repeated positions with id.</li>\n<li>Paging uses the same filter and order on every request.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>COUNT(*) includes an unmatched left-join row. COUNT(lesson.id) ignores its null child ID.&#x27;, &#x27;sql</p>"
      },
      {
        "name": "Transactions, Constraints and Indexes",
        "description": "Protect multi-step writes and index real query patterns.",
        "content": "<h2>Transactions, Constraints and Indexes</h2>\n<p><strong>Learning goal:</strong> Protect multi-step writes and index real query patterns.</p>\n<h3>Explanation</h3>\n<p>A transaction groups operations that commit or roll back together. A service-level precheck improves error messages but cannot replace a database constraint: another transaction can modify the data between a check and a write. Keep foreign keys active during normal application operations.</p>\n<p>Indexes help selected lookups but consume space and add work during writes. A composite index beginning with chapter_id can help a query filtering by chapter. PostgreSQL does not automatically index every referencing foreign-key column. Inspect an execution plan on representative data; a sequential scan may be the best choice for a tiny table.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">BEGIN;\nUPDATE lesson SET description = &#x27;Temporary workshop value&#x27; WHERE id = 1;\nSELECT id, description FROM lesson WHERE id = 1;\nROLLBACK;\nEXPLAIN SELECT * FROM lesson\nWHERE chapter_id = 1 ORDER BY sort_order, id;</code></pre>\n<h3>Practice task</h3>\n<p>In a training database, update a lesson inside a transaction and roll it back. Compare query plans before and after creating an index for a parent-filtered query.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The temporary description is not committed.</li>\n<li>The index matches the leading filter column.</li>\n<li>You explain write costs as well as read benefits.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Flushing SQL is not committing. Later errors can still roll back changes already sent to the database.&#x27;, &#x27;sql</p>"
      },
      {
        "name": "Liquibase Changesets and Seed Data",
        "description": "Evolve schema and content without rewriting applied migration history.",
        "content": "<h2>Liquibase Changesets and Seed Data</h2>\n<p><strong>Learning goal:</strong> Evolve schema and content without rewriting applied migration history.</p>\n<h3>Explanation</h3>\n<p>Liquibase records applied changesets in DATABASECHANGELOG using their ID, author and path. Checksums detect changes to previously applied definitions. Add a new changeset when evolving a shared database rather than rewriting a migration that other environments have already executed.</p>\n<p>Keep table creation before dependent inserts in the master changelog. Generated IDs and explicit parent lookup make content migrations safer than fixed numeric IDs. Define what should happen when seed content already exists, including duplicate course names. A rollback that deletes populated columns or content loses data; document this consequence instead of assuming rollback restores every business state.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">&lt;changeSet id=&quot;example-add-duration&quot; author=&quot;lms&quot;&gt;\n    &lt;addColumn tableName=&quot;lesson&quot;&gt;\n        &lt;column name=&quot;estimated_minutes&quot; type=&quot;INT&quot;/&gt;\n    &lt;/addColumn&gt;\n    &lt;rollback&gt;&lt;dropColumn tableName=&quot;lesson&quot; columnName=&quot;estimated_minutes&quot;/&gt;&lt;/rollback&gt;\n&lt;/changeSet&gt;\n&lt;!-- Illustrative exercise, not required by the current LMS. --&gt;</code></pre>\n<h3>Practice task</h3>\n<p>Create a duration changeset on an exercise branch, inspect generated SQL, and explain the consequences of rolling it back after values have been stored.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The changeset runs after table creation.</li>\n<li>A second startup does not apply it again.</li>\n<li>The rollback documentation explicitly covers data loss.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Do not clear checksums or mark changesets executed merely to silence a validation error. First establish which schema actually exists.&#x27;, &#x27;xml</p>"
      }
    ]
  },
  {
    "name": "Spring Boot Fundamentals",
    "description": "Understand startup, constructor injection, external configuration and transactional service boundaries.",
    "lessons": [
      {
        "name": "Application Startup and Component Scanning",
        "description": "Explain how Spring discovers controllers, services and configuration.",
        "content": "<h2>Application Startup and Component Scanning</h2>\n<p><strong>Learning goal:</strong> Explain how Spring discovers controllers, services and configuration.</p>\n<h3>Explanation</h3>\n<p>SpringApplication creates a context, processes configuration and starts the embedded server for a web application. @SpringBootApplication includes component scanning and auto-configuration. Place the application class in a root package above the normal controller and service packages.</p>\n<p>A Java class becomes a managed component through an annotation such as @Service or an explicit bean definition. Auto-configuration considers dependencies, properties and existing beans. Missing-bean errors often come from a package outside scanning or generated code that has not been rebuilt. Read the first meaningful cause in startup logs instead of masking it with a broad catch.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">package kz.edu.lms;\n@SpringBootApplication\npublic class LmsBackendApplication {\n    public static void main(String[] args) {\n        SpringApplication.run(LmsBackendApplication.class, args);\n    }\n}</code></pre>\n<h3>Practice task</h3>\n<p>Draw the package tree from the main application class to CourseController and CourseService. Explain what happens if the service is moved outside the scanned root.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Normal component packages are below the root.</li>\n<li>Every required service is registered once.</li>\n<li>You can trace a missing-bean failure to scanning or generation.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Do not edit MapStruct-generated implementation files to add @Component. Configure the mapper and regenerate it.</p>"
      },
      {
        "name": "Constructor Injection and Required Dependencies",
        "description": "Make collaborators explicit and test services without Spring startup.",
        "content": "<h2>Constructor Injection and Required Dependencies</h2>\n<p><strong>Learning goal:</strong> Make collaborators explicit and test services without Spring startup.</p>\n<h3>Explanation</h3>\n<p>Constructor injection shows which dependencies an object requires. final fields prevent replacement after construction, and a test can supply mocks directly. A single constructor can be used by Spring without explicitly marking it @Autowired.</p>\n<p>Lombok @RequiredArgsConstructor generates a constructor for final fields but does not register a bean; the @Service annotation still has a different purpose. Avoid circular service dependencies. A service can use more than one repository when it needs to find a parent and create a child. The repository count is less important than whether the business responsibility remains clear.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">@Service\n@RequiredArgsConstructor\npublic class CatalogService {\n    private final CourseRepository repository;\n    public boolean contains(Long id) {\n        return repository.existsById(id);\n    }\n}</code></pre>\n<h3>Practice task</h3>\n<p>Instantiate a CatalogService with a mock repository in a plain test. Stub an existing and a missing ID without starting Spring or PostgreSQL.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The dependency is private and final.</li>\n<li>The test supplies it through construction.</li>\n<li>No application context is needed to test contains.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Creating a service with new inside a controller bypasses Spring management and transaction proxies. Inject the registered service.</p>"
      },
      {
        "name": "Properties, Environment Variables and Profiles",
        "description": "Run the same application in an IDE and inside containers.",
        "content": "<h2>Properties, Environment Variables and Profiles</h2>\n<p><strong>Learning goal:</strong> Run the same application in an IDE and inside containers.</p>\n<h3>Explanation</h3>\n<p>The database address depends on where the application runs. localhost in the app container points back to that container, not the PostgreSQL container. Compose resolves service names within its network, so the app uses postgres:5432. A process on the host uses the published host port instead.</p>\n<p>Environment variables can override Spring configuration, including SPRING_DATASOURCE_URL. Profiles group environment-specific settings, while the core defaults remain shared. Keep private values out of committed examples. PostgreSQL initialization variables create users and databases only when initializing a data directory; changing an environment variable does not rewrite credentials in an existing database.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\"># IDE application.properties\nspring.datasource.url=jdbc:postgresql://localhost:5433/lms_db\n# Container environment:\n# SPRING_DATASOURCE_URL=jdbc:postgresql://postgres:5432/lms_db\n# SPRING_DATASOURCE_USERNAME=postgres\n# SPRING_DATASOURCE_PASSWORD=&lt;configured value&gt;</code></pre>\n<h3>Practice task</h3>\n<p>Document the database URL for IDE and container execution. Override the HTTP port through the environment without editing source code.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Each process uses the correct host and port.</li>\n<li>The same packaged application works with external configuration.</li>\n<li>Private credentials are excluded from version control.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>A host port mapping does not change the database port used between containers.&#x27;, &#x27;properties</p>"
      },
      {
        "name": "Service Transactions and Layered Responsibilities",
        "description": "Place business operations at a clear transaction boundary.",
        "content": "<h2>Service Transactions and Layered Responsibilities</h2>\n<p><strong>Learning goal:</strong> Place business operations at a clear transaction boundary.</p>\n<h3>Explanation</h3>\n<p>A controller handles HTTP input, a service coordinates business rules, a repository accesses entities, and a mapper converts representations. Keeping these roles clear makes tests smaller and error handling more consistent.</p>\n<p>Spring normally implements @Transactional through a proxy. Calls from another bean through the proxy are intercepted; a direct self-call inside the same instance does not add a new interception. Runtime exceptions trigger rollback by default. readOnly expresses intent and can affect optimization, but it is not a universal permission check that guarantees no SQL writes can occur.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">@Transactional\npublic void renameCourse(Long id, String name) {\n    Course course = courseRepository.findById(id)\n        .orElseThrow(() -&gt; new IllegalArgumentException(&quot;Course not found&quot;));\n    course.setName(name);\n}\n// Invoke through the Spring-managed service bean.</code></pre>\n<h3>Practice task</h3>\n<p>Trace a rename request through controller, service and repository. Identify where validation, missing-record handling and rollback happen.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The controller delegates business work.</li>\n<li>The write occurs inside a service transaction.</li>\n<li>A failure has defined rollback behavior.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>A private transactional helper called directly from the same instance does not activate a new proxy-based transaction.</p>"
      }
    ]
  },
  {
    "name": "REST APIs and Validation",
    "description": "Build HTTP contracts, validate DTOs, query nested resources and return consistent errors.",
    "lessons": [
      {
        "name": "HTTP Methods and Resource Routes",
        "description": "Choose methods and status codes that match each operation.",
        "content": "<h2>HTTP Methods and Resource Routes</h2>\n<p><strong>Learning goal:</strong> Choose methods and status codes that match each operation.</p>\n<h3>Explanation</h3>\n<p>GET retrieves data, POST commonly creates a resource, PUT replaces editable fields, and DELETE removes a resource. Sending a body with GET does not turn it into an update. Verify both the HTTP method and the URL when a request appears to have no effect.</p>\n<p>The LMS routes place chapters under courses and lessons under chapters. Such a URL asserts ownership, so a lookup must include the child ID and its parent ID. Return 201 for creation, 200 for a representation and 204 without a body for deletion. The request contract also needs to define what omitted optional fields mean during an update.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">PUT /api/chapters/10/lessons/25\nContent-Type: application/json\n\n{&quot;name&quot;:&quot;Updated lesson&quot;,&quot;description&quot;:&quot;New description&quot;, &quot;content&quot;:&quot;&lt;p&gt;New explanation&lt;/p&gt;&quot;,&quot;sortOrder&quot;:3}</code></pre>\n<h3>Practice task</h3>\n<p>Create, read, update and delete a disposable lesson in Postman. Try reading it under a different chapter ID.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Creation returns a generated ID and 201.</li>\n<li>PUT changes the selected lesson.</li>\n<li>The wrong parent gives 404.</li>\n<li>Deletion returns an empty 204.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>This API uses full editable-field updates: required fields must be present and omitted optional fields are cleared.&#x27;, &#x27;http</p>"
      },
      {
        "name": "Request DTOs and Bean Validation",
        "description": "Reject invalid input before invoking business operations.",
        "content": "<h2>Request DTOs and Bean Validation</h2>\n<p><strong>Learning goal:</strong> Reject invalid input before invoking business operations.</p>\n<h3>Explanation</h3>\n<p>A request DTO separates accepted input from persisted entities. @NotBlank rejects null and blank strings, and @Size limits length. Integer with @NotNull and @Min(1) represents a required positive position while preserving the distinction between missing and zero.</p>\n<p>Validation runs when a controller uses @Valid on its request body. Constructing a record in a unit test does not automatically trigger those annotations. A response DTO describes server output and does not need to repeat all input validation. Constraints such as parent existence or uniqueness under concurrency still need service or database checks.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">public record LessonCreateRequest(\n    @NotBlank @Size(max = 255) String name,\n    String description,\n    String content,\n    @NotNull @Min(1) Integer sortOrder\n) { }\n// Controller: @Valid @RequestBody LessonCreateRequest request</code></pre>\n<h3>Practice task</h3>\n<p>Send blank and missing names and null, zero and positive positions. Verify that invalid controller requests never invoke the service mock.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Valid input reaches the service once.</li>\n<li>Blank names and zero positions return 400.</li>\n<li>Missing sortOrder is rejected.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Using @NotNull on text still permits an empty string. Choose the constraint that represents the actual rule.</p>"
      },
      {
        "name": "Pagination and Parent-Scoped Queries",
        "description": "Bound query results while preserving order and parent ownership.",
        "content": "<h2>Pagination and Parent-Scoped Queries</h2>\n<p><strong>Learning goal:</strong> Bound query results while preserving order and parent ownership.</p>\n<h3>Explanation</h3>\n<p>Pageable holds page number, page size and sorting. This API numbers pages from zero. Page adds total-count metadata, which may require an additional count query. A repository query should filter by parent before returning a page, rather than loading every row into Java and discarding unrelated entries.</p>\n<p>Page.map converts entities to DTOs without losing pagination metadata. Position is not necessarily unique, so sortOrder followed by id gives a stable tie-breaker. An existing parent with no children returns an empty page; a missing parent returns 404 under this API contract. A size cap does not replace authorization or validation of allowable sort properties.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">Page&lt;Lesson&gt; findAllByChapterId(Long chapterId, Pageable pageable);\nOptional&lt;Lesson&gt; findByIdAndChapterId(Long id, Long chapterId);\n\n// Service, after confirming that the chapter exists:\nreturn lessonRepository.findAllByChapterId(chapterId, pageable)\n    .map(lessonMapper::toResponse);</code></pre>\n<h3>Practice task</h3>\n<p>Create several lessons, including matching positions, and retrieve pages of two records. Compare all IDs on a dataset that is not being concurrently edited.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Only the requested chapter is queried.</li>\n<li>Totals and page number are preserved.</li>\n<li>The ordering resolves ties by id.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Slicing a fully loaded Java list is not database pagination and can consume memory proportional to the entire table.</p>"
      },
      {
        "name": "Controller Advice and Error Contracts",
        "description": "Provide useful errors without exposing stack traces or SQL.",
        "content": "<h2>Controller Advice and Error Contracts</h2>\n<p><strong>Learning goal:</strong> Provide useful errors without exposing stack traces or SQL.</p>\n<h3>Explanation</h3>\n<p>@RestControllerAdvice applies exception handlers across controllers. Return a consistent error object with status, error and message. Validation failures should remain 400, missing resources 404 and deletion conflicts 409. A generic handler is only a final fallback.</p>\n<p>Unexpected failures belong in server logs with their diagnostic cause, while clients receive a generic 500 message. Do not serialize an exception or send SQL details to Postman. This assignment maps IllegalArgumentException to 404 for missing entities; larger applications often use a dedicated not-found exception so unrelated argument mistakes do not become resource errors.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">@ExceptionHandler(IllegalArgumentException.class)\npublic ResponseEntity&lt;ApiError&gt; notFound(IllegalArgumentException exception) {\n    return ResponseEntity.status(404).body(\n        new ApiError(404, &quot;Not Found&quot;, exception.getMessage()));\n}</code></pre>\n<h3>Practice task</h3>\n<p>Use MockMvc to exercise a missing lesson, malformed JSON and an unexpected runtime failure. Assert both the status and the body.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>404 has a useful public message.</li>\n<li>500 uses a generic message.</li>\n<li>No response contains a trace field or internal SQL.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>A catch-all must not turn ordinary framework errors such as invalid JSON into 500 responses.</p>"
      }
    ]
  },
  {
    "name": "Persistence with JPA",
    "description": "Map entities and relationships, use repositories, update managed objects and diagnose lazy-loading query problems.",
    "lessons": [
      {
        "name": "Entity Mapping and Generated Identifiers",
        "description": "Map entity fields to schema constraints without mixing in API concerns.",
        "content": "<h2>Entity Mapping and Generated Identifiers</h2>\n<p><strong>Learning goal:</strong> Map entity fields to schema constraints without mixing in API concerns.</p>\n<h3>Explanation</h3>\n<p>An @Entity class maps to persistent data and needs an accessible no-argument constructor. @Id identifies the primary key, while @GeneratedValue defines how IDs are assigned. @MappedSuperclass contributes inherited mappings without creating a separate entity table. This is why BaseEntity supplies id and audit timestamps to each LMS entity.</p>\n<p>Column nullability and SQL types should agree with Liquibase. Hibernate validate checks mapping compatibility at startup; it does not create missing tables. Keep DTO validation separate from column declarations. A nullable=false string column rejects null but not blank text, and an int field defaults to zero unless the application assigns another value.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">@Entity\npublic class Lesson extends BaseEntity {\n    @Column(nullable = false)\n    private String name;\n    @Column(columnDefinition = &quot;TEXT&quot;)\n    private String content;\n    @ManyToOne(fetch = FetchType.LAZY)\n    @JoinColumn(name = &quot;chapter_id&quot;, nullable = false)\n    private Chapter chapter;\n    // Add the needed accessors; no explicit constructor means a default one exists.\n}</code></pre>\n<h3>Practice task</h3>\n<p>Compare Lesson fields with the lesson migration. Explain which constraints come from Java validation, which from the schema, and which require business logic.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>ID generation matches the identity column.</li>\n<li>chapter_id has the expected foreign key and nullability.</li>\n<li>The entity and migration use the same table and column names.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Changing @Table alone does not rename an existing table. Schema changes need a corresponding migration.</p>"
      },
      {
        "name": "Derived Queries and Ownership Checks",
        "description": "Express repository lookups that match nested API contracts.",
        "content": "<h2>Derived Queries and Ownership Checks</h2>\n<p><strong>Learning goal:</strong> Express repository lookups that match nested API contracts.</p>\n<h3>Explanation</h3>\n<p>Spring Data derives query predicates from method names such as findByIdAndChapterId. Returning Optional expresses that no matching record may exist. A method returning Lesson directly does not have Optional.orElseThrow; the repository return type determines what the caller can do.</p>\n<p>Use both IDs when an endpoint names both the chapter and the lesson. A globally unique lesson ID does not justify ignoring the chapter parameter: the caller&#x27;s requested relationship still needs validation. A collection query normally returns an empty page for no matches. The service can separately decide whether the parent must exist before querying that page.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">public interface LessonRepository extends JpaRepository&lt;Lesson, Long&gt; {\n    Optional&lt;Lesson&gt; findByIdAndChapterId(Long id, Long chapterId);\n    Page&lt;Lesson&gt; findAllByChapterId(Long chapterId, Pageable pageable);\n}</code></pre>\n<h3>Practice task</h3>\n<p>Create service tests with lessonId=25 and chapterId=10. Then call the service with chapterId=99 and verify that the repository receives that parent ID instead of an unrestricted lookup.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Correct ownership returns a DTO.</li>\n<li>Wrong ownership returns the defined not-found error.</li>\n<li>The test verifies both repository arguments.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>A mock that returns a lesson for any arguments can hide a swapped-ID defect. Stub the exact IDs in ownership tests.</p>"
      },
      {
        "name": "Dirty Checking, Flush and Auditing",
        "description": "Understand when managed changes reach SQL and when response timestamps are populated.",
        "content": "<h2>Dirty Checking, Flush and Auditing</h2>\n<p><strong>Learning goal:</strong> Understand when managed changes reach SQL and when response timestamps are populated.</p>\n<h3>Explanation</h3>\n<p>An entity loaded inside an active persistence context is managed. Hibernate detects changes to its mapped fields and writes them when the context is flushed. A service transaction therefore can update an existing entity without constructing a replacement or explicitly saving a detached copy.</p>\n<p>flush synchronizes pending changes with the database, but the transaction can still roll back. Auditing callbacks may run during that synchronization. If an update response must contain the audit timestamp after modification, flush before mapping to an immutable response DTO. This does not mean every read or every create needs an extra flush. Avoid creating SQL traffic without a concrete reason.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">@Transactional\npublic LessonResponse rename(Long chapterId, Long lessonId, LessonUpdateRequest request) {\n    Lesson lesson = repository.findByIdAndChapterId(lessonId, chapterId)\n        .orElseThrow(() -&gt; new IllegalArgumentException(&quot;Lesson not found&quot;));\n    mapper.updateEntity(request, lesson);\n    repository.flush();\n    return mapper.toResponse(lesson);\n}</code></pre>\n<h3>Practice task</h3>\n<p>Compare update behavior with and without an explicit flush before response mapping. Inspect both the returned updatedTime and a later database read.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The original ID and parent relationship stay unchanged.</li>\n<li>Only editable fields are updated.</li>\n<li>The distinction between flushing and committing is clear.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>A new entity with no ID passed to save normally represents creation, not an update. Load the existing entity before applying an update DTO.</p>"
      },
      {
        "name": "Lazy Loading, N+1 and DTO Boundaries",
        "description": "Detect unnecessary queries before adding fetch strategies.",
        "content": "<h2>Lazy Loading, N+1 and DTO Boundaries</h2>\n<p><strong>Learning goal:</strong> Detect unnecessary queries before adding fetch strategies.</p>\n<h3>Explanation</h3>\n<p>LAZY requests defer relationship loading until needed. Accessing a parent through many separately loaded children can produce an N+1 pattern: one initial query followed by additional related-data queries. A fetch join or entity graph may help a particular use case, but globally switching every relationship to EAGER usually moves the problem instead of solving it.</p>\n<p>Map entities to DTOs within an appropriate service boundary. Returning entities directly can expose persistence internals, recurse through relationships or trigger lazy queries during JSON serialization. Collection fetch joins and pagination need particular care because join rows can duplicate parents. Measure the generated SQL for the endpoint you are optimizing.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">// Example repository method when a use case needs the parent:\n@EntityGraph(attributePaths = &quot;chapter&quot;)\nOptional&lt;Lesson&gt; findByIdAndChapterId(Long id, Long chapterId);\n// Add a graph only when the returned representation needs chapter data.</code></pre>\n<h3>Practice task</h3>\n<p>Enable SQL observation in a development run and count queries for a lesson list. Explain whether its current DTO actually requires loading each chapter.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The measured query count supports the diagnosis.</li>\n<li>The solution loads only data needed by the response.</li>\n<li>Entity relationships are not directly serialized to clients.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Adding an entity graph to every query can over-fetch data. An optimization should address a demonstrated access pattern.</p>"
      }
    ]
  },
  {
    "name": "Testing with JUnit and Mockito",
    "description": "Write regression tests for services, HTTP contracts, validation and database-specific behavior.",
    "lessons": [
      {
        "name": "JUnit Assertions and Test Structure",
        "description": "Write tests that describe behavior with deterministic inputs.",
        "content": "<h2>JUnit Assertions and Test Structure</h2>\n<p><strong>Learning goal:</strong> Write tests that describe behavior with deterministic inputs.</p>\n<h3>Explanation</h3>\n<p>A useful test has a clear setup, one business action and assertions about observable results. Names should state the behavior, such as missingChapterReturns404, rather than merely repeating a method name. Cover boundaries that would expose a defect: empty input, invalid ranges and ownership mismatch.</p>\n<p>Assertions should explain the expected contract. Checking only that a result is non-null misses wrong fields and incorrect IDs. Deterministic fixtures avoid system time and arbitrary random values unless the test records enough information to reproduce a failure. Keep each test independent so ordering and previous runs do not affect it.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">@Test\nvoid calculatesRemainingLessons() {\n    int completed = 3;\n    int total = 10;\n    int remaining = Progress.remaining(completed, total);\n    assertEquals(7, remaining);\n}\n// Progress is the helper from the Java essentials workshop.</code></pre>\n<h3>Practice task</h3>\n<p>Add tests for normal progress, fully completed progress and invalid completed &gt; total. Use assertThrows to specify the invalid-input behavior.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The success case checks the exact result.</li>\n<li>The boundary case returns zero.</li>\n<li>The invalid case checks the exception type and useful message.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>A test that copies the implementation&#x27;s formula into its expected result may reproduce the same bug. Use independently calculated examples.</p>"
      },
      {
        "name": "Mockito Repositories and Real Mappers",
        "description": "Isolate storage while checking actual DTO conversion.",
        "content": "<h2>Mockito Repositories and Real Mappers</h2>\n<p><strong>Learning goal:</strong> Isolate storage while checking actual DTO conversion.</p>\n<h3>Explanation</h3>\n<p>Mockito can replace a repository so service tests need no database. Stub the behavior the scenario depends on and verify essential calls, such as using both parent and child IDs. Do not stub every method preemptively; unnecessary stubs can hide what the test actually requires.</p>\n<p>Using a real generated mapper in a service test verifies the entity-to-DTO contract as well as orchestration. A save answer can simulate assigning an ID, while a flush answer can simulate an audit timestamp for the response. These simulations test service behavior, not Hibernate itself. Separate persistence tests are needed to prove real constraints and callbacks.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">when(repository.findByIdAndChapterId(25L, 10L))\n    .thenReturn(Optional.of(lesson));\nLessonResponse result = service.getLessonById(10L, 25L);\nassertEquals(25L, result.id());\nverify(repository).findByIdAndChapterId(25L, 10L);</code></pre>\n<h3>Practice task</h3>\n<p>Write service tests for creation under an existing parent and failure under a missing parent. Capture the saved lesson and inspect its chapter, content and sortOrder.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The correct parent instance is assigned.</li>\n<li>The response contains the generated ID.</li>\n<li>No save occurs when the parent is absent.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Mocking the mapper to return the exact response asserted by the test can miss a broken mapping. Choose mocks according to the boundary being isolated.</p>"
      },
      {
        "name": "MockMvc and Controller Contracts",
        "description": "Test routing, validation and advice through the HTTP layer.",
        "content": "<h2>MockMvc and Controller Contracts</h2>\n<p><strong>Learning goal:</strong> Test routing, validation and advice through the HTTP layer.</p>\n<h3>Explanation</h3>\n<p>MockMvc invokes the Spring MVC request pipeline without requiring an external HTTP server. It can check path variables, request-body deserialization, validation, status codes and JSON fields. Mock the service for controller tests so a routing failure is not confused with a database failure.</p>\n<p>Standalone setup must register the advice, validator and any custom argument resolvers needed by the controller, including Pageable support. A web-slice test provides a different option with framework configuration. Test successful POST and PUT separately, and verify invalid input is rejected before the service call. A 204 response should have an empty body.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">mvc.perform(post(&quot;/api/chapters/10/lessons&quot;)\n        .contentType(MediaType.APPLICATION_JSON)\n        .content(&quot;&quot;&quot;\n                {&quot;name&quot;:&quot;Variables&quot;,&quot;sortOrder&quot;:1}\n                &quot;&quot;&quot;))\n    .andExpect(status().isCreated())\n    .andExpect(jsonPath(&quot;$.id&quot;).value(25));\n// Stub createLesson(...) before executing the request.</code></pre>\n<h3>Practice task</h3>\n<p>Add a successful create test, a blank-name test and a wrong-parent read test. Confirm the last two do not falsely report a successful status.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The success case checks the JSON representation.</li>\n<li>Invalid DTO input gives 400 and no service invocation.</li>\n<li>The advice converts the not-found exception into 404.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Calling the controller method directly does not test JSON binding, @Valid, route matching or exception advice.</p>"
      },
      {
        "name": "Integration Tests and a Regression Workflow",
        "description": "Separate fast isolated checks from tests requiring real infrastructure.",
        "content": "<h2>Integration Tests and a Regression Workflow</h2>\n<p><strong>Learning goal:</strong> Separate fast isolated checks from tests requiring real infrastructure.</p>\n<h3>Explanation</h3>\n<p>Unit tests with mocked repositories are fast and useful, but they cannot prove SQL correctness, migrations or foreign-key behavior. Integration tests should use an isolated PostgreSQL database or container, apply the actual migrations and exercise representative repository operations.</p>\n<p>Avoid pointing automated write tests at a personal development database. A test should clean up its own data or discard its isolated database after the run. Before publishing, run the fast service and controller suite, then the relevant database and packaging checks. A test report with only successful compilation is not evidence that the tests executed.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\"># PowerShell: fast tests from the project directory\n.\\gradlew.bat test --tests &quot;*ServiceTest&quot; --tests &quot;*ControllerTest&quot;\n# Inspect build/reports/tests/test/index.html\n# Database tests need a deliberately isolated datasource.</code></pre>\n<h3>Practice task</h3>\n<p>Design a database test that tries to delete a chapter containing a lesson. Explain what a mocked repository test can verify and what only PostgreSQL can prove.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The database test uses isolated storage.</li>\n<li>The real foreign key blocks invalid deletion.</li>\n<li>The report records executed tests and failures.</li>\n<li>Test runs do not leave rows in a personal database.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Disabling assertions or skipping failing tests can produce a green build while removing regression protection.&#x27;, &#x27;powershell</p>"
      }
    ]
  },
  {
    "name": "Observability and API Documentation",
    "description": "Use purposeful logs, define OpenAPI contracts and investigate failures from evidence.",
    "lessons": [
      {
        "name": "SLF4J Levels and Useful Messages",
        "description": "Choose INFO, DEBUG and ERROR messages that help explain application behavior.",
        "content": "<h2>SLF4J Levels and Useful Messages</h2>\n<p><strong>Learning goal:</strong> Choose INFO, DEBUG and ERROR messages that help explain application behavior.</p>\n<h3>Explanation</h3>\n<p>SLF4J is a logging API; Spring Boot&#x27;s logging setup supplies an implementation. Lombok @Slf4j generates a logger field but is not a separate logging backend. INFO describes an operation, DEBUG records diagnostic fields, and ERROR records a failure according to the policy used in this assignment.</p>\n<p>Parameterized logging uses placeholders rather than eager string concatenation. When reporting an unexpected exception, preserve the throwable in server logs while returning a safe client message. Never log credentials, tokens or unbounded sensitive request bodies. Educational content can be useful at DEBUG in development, but production logging needs an explicit data policy.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">log.info(&quot;Creating new lesson&quot;);\nlog.debug(&quot;Lesson request: chapterId={}, name={}, sortOrder={}&quot;,\n    chapterId, request.name(), request.sortOrder());\n// In the central error handler:\nlog.error(&quot;Unexpected request processing error&quot;, exception);</code></pre>\n<h3>Practice task</h3>\n<p>Create a lesson and inspect INFO and DEBUG output. Then trigger a missing-resource error and confirm the response remains separate from the server diagnostic log.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>INFO identifies the operation clearly.</li>\n<li>DEBUG includes useful IDs or fields.</li>\n<li>Credentials are absent.</li>\n<li>Unexpected exceptions retain server-side diagnostic context.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Logging &quot;successfully committed&quot; before the transaction commits can be misleading. Use wording that matches the point where the log is emitted.</p>"
      },
      {
        "name": "OpenAPI Schemas and Endpoint Documentation",
        "description": "Describe actual requests, responses and constraints in Swagger UI.",
        "content": "<h2>OpenAPI Schemas and Endpoint Documentation</h2>\n<p><strong>Learning goal:</strong> Describe actual requests, responses and constraints in Swagger UI.</p>\n<h3>Explanation</h3>\n<p>OpenAPI describes the API contract, and Swagger UI renders that contract interactively. Group related controllers with tags, describe each operation, and annotate DTO fields with meaningful examples. Keep documentation aligned with actual validation and route behavior.</p>\n<p>List success statuses and expected errors using the shared ApiError schema. A create operation returning 201 should not be documented only as 200. Pageable parameters should appear as page, size and sort rather than an unexplained Java object. Examples must use parent IDs that the reader replaces with real data instead of implying sample IDs always exist.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">@Operation(summary = &quot;Create a lesson&quot;, description = &quot;Creates a lesson in an existing chapter&quot;)\n@ApiResponse(responseCode = &quot;201&quot;, description = &quot;Lesson created&quot;, useReturnTypeSchema = true)\n@PostMapping\npublic ResponseEntity&lt;LessonResponse&gt; create(\n        @PathVariable Long chapterId, @Valid @RequestBody LessonCreateRequest request) {\n    return ResponseEntity.status(201).body(service.createLesson(chapterId, request));\n}</code></pre>\n<h3>Practice task</h3>\n<p>Open Swagger UI, inspect one POST and one paginated GET, then compare their generated specification with the controller and DTO definitions.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>Every operation has a useful summary.</li>\n<li>Required fields and examples match validation.</li>\n<li>Error schemas contain no stack trace.</li>\n<li>The generated specification is reachable.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Documenting a response code does not implement it. The controller or advice must actually return that status.</p>"
      },
      {
        "name": "Troubleshooting from HTTP to Database",
        "description": "Narrow a failure using the request, response and server logs.",
        "content": "<h2>Troubleshooting from HTTP to Database</h2>\n<p><strong>Learning goal:</strong> Narrow a failure using the request, response and server logs.</p>\n<h3>Explanation</h3>\n<p>Start with the exact HTTP method, path, body, status and response. A GET request cannot validate whether a PUT update works. A 404 may mean a route mismatch or an entity missing within a particular parent; read the response and inspect the controller mapping before changing repository code.</p>\n<p>Follow the request through layers: validation, service lookup, mapper, repository and transaction. For a startup failure, inspect configuration and dependency errors before trying API requests. For a database constraint failure, identify the constraint and the conflicting relationship. Make one hypothesis at a time and use evidence that can disprove it.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">GET /api/chapters/10/lessons/25\n\n# If this returns 404:\n# 1. Confirm lesson 25 exists.\n# 2. Confirm its chapter_id is 10.\n# 3. Confirm the request reaches the expected app instance.\n# 4. Compare the public message and server log.</code></pre>\n<h3>Practice task</h3>\n<p>Write a short incident note for a wrong-parent 404 and a conflicting port startup. Include the initial symptom, evidence, cause and corrective action.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The note contains the exact request or startup command.</li>\n<li>The cause is supported by evidence.</li>\n<li>The fix addresses the cause rather than hiding the symptom.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Adding save(), flush() or try/catch everywhere can obscure the real issue. Understand which layer failed before editing it.&#x27;, &#x27;http</p>"
      },
      {
        "name": "Operational Review and API Acceptance",
        "description": "Validate a release using a repeatable sequence of realistic actions.",
        "content": "<h2>Operational Review and API Acceptance</h2>\n<p><strong>Learning goal:</strong> Validate a release using a repeatable sequence of realistic actions.</p>\n<h3>Explanation</h3>\n<p>A release check should verify a coherent user journey, not only whether the server starts. Create a course, add a chapter, create lessons, update their order and retrieve paginated results. Then exercise expected errors: invalid input, missing parents and deletion blocked by children.</p>\n<p>Keep the checklist specific enough that another developer can repeat it. Record which image tag, database and configuration were used. Distinguish documentation checks, unit tests and real database checks. A passing mocked test suite cannot confirm a container&#x27;s datasource address; a running container cannot confirm every service edge case.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">Release checklist:\n1. Start the chosen image and wait for readiness.\n2. Verify /v3/api-docs and Swagger UI.\n3. Run the course -&gt; chapter -&gt; lesson workflow.\n4. Verify 400, 404 and 409 responses.\n5. Restart and confirm the expected data still exists.</code></pre>\n<h3>Practice task</h3>\n<p>Create an acceptance checklist for the LMS and run it in an isolated environment. Use descriptive sample names and record generated IDs for later requests.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The workflow includes reads and writes.</li>\n<li>Expected error bodies are checked.</li>\n<li>A restart confirms storage behavior.</li>\n<li>The tested image tag is recorded.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>A green health indicator confirms only what its probe checks. It is not proof that every business endpoint is correct.&#x27;, &#x27;text</p>"
      }
    ]
  },
  {
    "name": "Docker and Delivery",
    "description": "Package the service, connect it to PostgreSQL, protect persistent data and publish a reproducible release.",
    "lessons": [
      {
        "name": "Multi-Stage Java Images",
        "description": "Separate build tools from the runtime image.",
        "content": "<h2>Multi-Stage Java Images</h2>\n<p><strong>Learning goal:</strong> Separate build tools from the runtime image.</p>\n<h3>Explanation</h3>\n<p>A multi-stage Dockerfile can compile with a JDK and copy only the executable JAR into a smaller JRE image. The Gradle wrapper keeps the build tool version in the repository. .dockerignore excludes local caches, build outputs and private environment files from the build context.</p>\n<p>The runtime process should not need root privileges. Copy the artifact to a predictable path and run Java as a non-root user. Test execution is a separate release step if the image build skips tests. A successful bootJar build proves packaging, not database readiness or complete runtime behavior.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">FROM eclipse-temurin:21-jdk-jammy AS build\nWORKDIR /workspace\nCOPY . .\nRUN sed -i &#x27;s/\\r$//&#x27; gradlew &amp;&amp; chmod +x gradlew\nRUN ./gradlew --no-daemon bootJar -x test\n# Production Dockerfile: copy the selected executable JAR into a Java 21 JRE stage.\n# Avoid copying a *-plain.jar as the executable application.</code></pre>\n<h3>Practice task</h3>\n<p>Inspect the project Dockerfile and identify the build and runtime stages. Verify which JAR is selected and why .dockerignore matters.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The runtime image does not depend on a host JDK.</li>\n<li>The executable Boot JAR is selected.</li>\n<li>Source control data and local caches are excluded.</li>\n<li>Tests run before publication.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>EXPOSE documents a container port but does not publish it on the host. Compose ports or docker run -p create that mapping.&#x27;, &#x27;dockerfile</p>"
      },
      {
        "name": "Compose Networking, Ports and Readiness",
        "description": "Connect containers using service names and diagnose host-port conflicts.",
        "content": "<h2>Compose Networking, Ports and Readiness</h2>\n<p><strong>Learning goal:</strong> Connect containers using service names and diagnose host-port conflicts.</p>\n<h3>Explanation</h3>\n<p>Each container has its own network namespace. The application connects to PostgreSQL by the Compose service name and container port, while tools on the host use the published host port. In a mapping such as 8081:8080, 8081 belongs to the host and 8080 belongs to the app container.</p>\n<p>Creation order does not prove that a database is ready to accept connections. Use a PostgreSQL healthcheck and depends_on with service_healthy for the initial startup dependency. This controls startup readiness, not permanent availability; a database can still fail later and the application must handle connection errors.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">app:\n  ports:\n    - &quot;8081:8080&quot;\n  environment:\n    SPRING_DATASOURCE_URL: jdbc:postgresql://postgres:5432/lms_db\n  depends_on:\n    postgres:\n      condition: service_healthy\n# postgres must define a healthcheck in the complete compose.yaml.</code></pre>\n<h3>Practice task</h3>\n<p>Run the IDE application on 8080 and the container on 8081. Confirm which URL reaches each instance and which address each uses for PostgreSQL.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>No two processes claim the same host port.</li>\n<li>Containers use postgres:5432 internally.</li>\n<li>The application waits for the defined database healthcheck.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Changing the external PostgreSQL port to 5433 does not mean the app container should connect to postgres:5433.&#x27;, &#x27;yaml</p>"
      },
      {
        "name": "Persistent Volumes, Backups and Migrations",
        "description": "Keep database data outside replaceable containers and test recovery.",
        "content": "<h2>Persistent Volumes, Backups and Migrations</h2>\n<p><strong>Learning goal:</strong> Keep database data outside replaceable containers and test recovery.</p>\n<h3>Explanation</h3>\n<p>Container images package software, while database volumes hold runtime data. Rebuilding an application image should not erase rows, but removing or replacing a database volume can. Named and anonymous volumes have different operational handling; know which one your running PostgreSQL container uses before recreating it.</p>\n<p>A backup is useful only if restoration has been tested. A logical pg_dump can be restored into a separate compatible database for verification. Do not copy live database files casually between major PostgreSQL versions. Image tags such as latest can move between major releases, so pinning versions and planning upgrades are operational decisions, not cosmetic changes.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\"># Read-only inspection commands\n docker inspect lms-postgres --format &#x27;{{json .Mounts}}&#x27;\n docker compose ps\n# For routine pauses, keep existing containers and their mounts:\n docker compose stop\n docker compose start</code></pre>\n<h3>Practice task</h3>\n<p>Identify the current PostgreSQL mount, document how it is preserved, and design a backup/restore drill against a separate database. Do not test restoration by overwriting the only working copy.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The actual storage location is known.</li>\n<li>The recovery destination is separate.</li>\n<li>Row counts and relationships are checked after restoration.</li>\n<li>A major-version upgrade has a deliberate plan.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>A published application image does not contain the live database. Initial Liquibase lessons and users&#x27; later edits are different kinds of data.&#x27;, &#x27;powershell</p>"
      },
      {
        "name": "Capstone: Publish and Demonstrate the LMS",
        "description": "Deliver a tagged image and a repeatable end-to-end demonstration.",
        "content": "<h2>Capstone: Publish and Demonstrate the LMS</h2>\n<p><strong>Learning goal:</strong> Deliver a tagged image and a repeatable end-to-end demonstration.</p>\n<h3>Explanation</h3>\n<p>A release is more than a successful docker push. It includes source history, a known image tag, configuration instructions, database initialization and evidence that a user journey works. Use an explicit version tag for a release so the mentor can identify what was tested.</p>\n<p>Publish the application image to your own Docker Hub repository and use Compose to run it with PostgreSQL. Keep registry authentication out of source files. On a fresh database, Liquibase creates the schema and seed content; on an existing database it applies only pending changesets. Verify the image through a separate run rather than assuming the local IDE output proves it.</p>\n<h3>Worked example</h3>\n<p>Run this focused example in an appropriate Java class, test, SQL console, or project file as indicated. Framework snippets assume the imports and dependencies introduced in the chapter.</p>\n<pre><code class=\"language-java\">docker login\n$env:APP_IMAGE = &quot;YOUR_DOCKERHUB_USERNAME/lms-backend:1.0.0&quot;\ndocker compose build app\ndocker compose push app\n# In the release verification environment:\ndocker compose pull\ndocker compose up -d --no-build</code></pre>\n<h3>Practice task</h3>\n<p>Prepare a demo that starts from a fresh isolated database, opens Swagger, lists the course curriculum and performs lesson CRUD. Include successful unit tests, expected errors and a restart check.</p>\n<h3>Acceptance criteria</h3>\n<ul>\n<li>The tag matches the tested release.</li>\n<li>The mentor can follow the README without a local JDK.</li>\n<li>The fresh database contains meaningful lessons.</li>\n<li>Existing records survive an ordinary restart.</li>\n<li>No credentials or database dump are included in the image.</li>\n</ul>\n<h3>Common mistake</h3>\n<p>Publishing latest repeatedly makes it difficult to know which build a tester used. Keep a release tag even if you also maintain latest.&#x27;, &#x27;powershell</p>"
      }
    ]
  }
]
$curriculum$::jsonb;
    chapter_data jsonb;
    lesson_data jsonb;
    course_key bigint;
    chapter_key bigint;
    matches bigint;
    next_position integer;
BEGIN
    -- Prevent concurrent writers from creating duplicate names while seeding.
    LOCK TABLE courses, chapter, lesson IN SHARE ROW EXCLUSIVE MODE;
    SELECT count(*), min(id) INTO matches, course_key
      FROM courses WHERE name = 'Java Developer';
    IF matches > 1 THEN
        RAISE EXCEPTION 'Curriculum migration requires a unique course named Java Developer; found %', matches;
    END IF;
    IF matches = 0 THEN
        INSERT INTO courses(name, description, created_time, updated_time)
        VALUES ('Java Developer',
                'A practical Java 21 and Spring Boot course: language fundamentals, SQL, REST APIs, JPA, testing, observability and Docker delivery. Each lesson includes a worked example, a practice task and acceptance criteria. Build and ship a learning management backend.',
                CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
        RETURNING id INTO course_key;
    ELSE
        -- Upgrade only the original seed description; preserve user-written descriptions.
        UPDATE courses
           SET description = 'A practical Java 21 and Spring Boot course: language fundamentals, SQL, REST APIs, JPA, testing, observability and Docker delivery. Each lesson includes a worked example, a practice task and acceptance criteria. Build and ship a learning management backend.',
               updated_time = CURRENT_TIMESTAMP
         WHERE id = course_key
           AND description = 'Learn Java fundamentals, control flow, and object-oriented programming through explanations and practical exercises.';
    END IF;

    FOR chapter_data IN SELECT value FROM jsonb_array_elements(curriculum)
    LOOP
        SELECT count(*), min(id) INTO matches, chapter_key
          FROM chapter WHERE course_id = course_key AND name = chapter_data->>'name';
        IF matches > 1 THEN
            RAISE EXCEPTION 'Ambiguous chapter name % in course %', chapter_data->>'name', course_key;
        END IF;
        IF matches = 0 THEN
            IF chapter_data->>'name' = 'Java Development Essentials' THEN
                -- Put foundations first while preserving the relative order of existing chapters.
                UPDATE chapter SET sort_order = sort_order + 1, updated_time = CURRENT_TIMESTAMP
                 WHERE course_id = course_key;
                next_position := 1;
            ELSE
                SELECT COALESCE(max(sort_order), 0) + 1 INTO next_position
                  FROM chapter WHERE course_id = course_key;
            END IF;
            INSERT INTO chapter(name, description, sort_order, course_id, created_time, updated_time)
            VALUES (chapter_data->>'name', chapter_data->>'description', next_position,
                    course_key, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
            RETURNING id INTO chapter_key;
        END IF;

        FOR lesson_data IN SELECT value FROM jsonb_array_elements(chapter_data->'lessons')
        LOOP
            IF NOT EXISTS (SELECT 1 FROM lesson
                           WHERE chapter_id = chapter_key AND name = lesson_data->>'name') THEN
                SELECT COALESCE(max(sort_order), 0) + 1 INTO next_position
                  FROM lesson WHERE chapter_id = chapter_key;
                INSERT INTO lesson(name, description, content, sort_order, chapter_id, created_time, updated_time)
                VALUES (lesson_data->>'name', lesson_data->>'description', lesson_data->>'content',
                        next_position, chapter_key, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
            END IF;
        END LOOP;
    END LOOP;
END;
$migration$;
